class KNeighborsClassifier:
    def __init__(self, n_neighbors=3):
        self.n_neighbors = n_neighbors
        self.X_train = None
        self.y_train = None

    def fit(self, X, y):
        self.X_train = np.array(X)
        self.y_train = np.array(y)

    def predict(self, X_test):
        X_test = np.array(X_test)
        predictions = []

        for test_point in X_test:
            distances = []

            # Calculate distances to all training points
            for i in range(len(self.X_train)):
                dist = math.sqrt(np.sum((test_point - self.X_train[i]) ** 2))
                distances.append((dist, self.y_train[i]))

            # Sort by distance and get k nearest
            distances.sort(key=lambda x: x[0])
            neighbors = distances[:self.n_neighbors]

            # Count votes
            votes = {}
            for _, label in neighbors:
                votes[label] = votes.get(label, 0) + 1

            # Get most common class
            predicted_class = max(votes, key=votes.get)
            predictions.append(predicted_class)

        return np.array(predictions)
knn = KNeighborsClassifier(n_neighbors=3)  # môžeš zmeniť počet susedov
knn.fit(X_hardcoded, y_hardcoded)

class ColorDetector():
    def __init__(self, color):
        self.detected_color = color
    
    def update_color(self, color):
        self.detected_color = color
    
    def is_detecting_black(self):
        r, g, b = self.detected_color
        #print(f"COLOR: {self.detected_color} IS BLACK: {r < 40 and g < 40 and b < 40}")
        return r < 40 and g < 40 and b < 40

    def detect_colors(self, mapping):
        r, g, b = self.detected_color
        
        if int(round(mapping.robot_x_position)) % 12 == 0 and int(round(mapping.robot_y_position)) % 12 == 0:
            if r > 240 and g > 240 and 60 > b > 70:
                print("yellow")
                mapping.special_tiles[(int(round(mapping.robot_x_position)), int(round(mapping.robot_y_position)))] = "y"
            elif 40 < r < 172 and 40 < g < 172 and 40 < b < 172:
                print("checkpoint")
                mapping.special_tiles[(int(round(mapping.robot_x_position)), int(round(mapping.robot_y_position)))] = "4"
            elif r < 60 and g < 60 and b > 200:
                print("blue")
                mapping.special_tiles[(int(round(mapping.robot_x_position)), int(round(mapping.robot_y_position)))] = "b"
            elif 200 > r > 180 and 200 > g > 145 and 100 > b > 80:
                print("swamp")
                mapping.special_tiles[(int(round(mapping.robot_x_position)), int(round(mapping.robot_y_position)))] = "3"
            elif 35 > r and g > 220 and 35 > b:
                print("green")
                mapping.special_tiles[(int(round(mapping.robot_x_position)), int(round(mapping.robot_y_position)))] = "g"
            elif r > 220 and g < 60 and b < 60:
                print("red")
                mapping.special_tiles[(int(round(mapping.robot_x_position)), int(round(mapping.robot_y_position)))] = "r"
            elif 140 > r > 120 and g < 60 and b > 200:
                print("purple")
                mapping.special_tiles[(int(round(mapping.robot_x_position)), int(round(mapping.robot_y_position)))] = "p"
            else:
                pass
                #print(f"{self.detected_color}")

class Recognition():
    def __init__(self, r):
        self.detected_image = False
        self.rotation_diff = r

    def determine_image_type(self, frame):
            resized = self.get_features(frame)
            resized = knn.predict([resized])[0]
            return str(resized)


    def crop_rotated_bounding_box(self, image, center, size, angle):
        """
        Crop a rotated bounding box from an image, preserving the natural background.
        :param image: Input image (numpy array).
        :param center: Tuple (x, y) of the box's center.
        :param size: Tuple (width, height) of the box.
        :param angle: Rotation angle in degrees (from cv2.minAreaRect).
        :return: Cropped image region or None if cropping fails.
        """

        h, w = image.shape[:2]
        cx, cy = center
        width, height = size

        # Pad the image to handle rotation artifacts
        pad_size = int(max(width, height) * 0.5)
        padded = cv2.copyMakeBorder(image, pad_size, pad_size, pad_size, pad_size, cv2.BORDER_CONSTANT, value=0)
        cx_padded = cx + pad_size
        cy_padded = cy + pad_size

        # Handle minAreaRect angle: angle is in [-90, 0), and width/height may need swapping
        adjusted_angle = angle
        if angle < -45:
            adjusted_angle = angle + 90
            width, height = height, width  # Swap width and height

        # Rotate the image to align the bounding box with axes
        M = cv2.getRotationMatrix2D((cx_padded, cy_padded), adjusted_angle, 1.0)
        rotated = cv2.warpAffine(padded, M, (w + 2 * pad_size, h + 2 * pad_size))

        # Compute the crop coordinates (now axis-aligned after rotation)
        top_left_x = int(cx_padded - width / 2)
        top_left_y = int(cy_padded - height / 2)
        new_width = int(width)
        new_height = int(height)

        # Clip coordinates
        top_left_x = max(0, top_left_x)
        top_left_y = max(0, top_left_y)
        bottom_right_x = min(rotated.shape[1], top_left_x + new_width)
        bottom_right_y = min(rotated.shape[0], top_left_y + new_height)

        new_width = bottom_right_x - top_left_x
        new_height = bottom_right_y - top_left_y

        # Crop the region
        cropped = rotated[top_left_y:top_left_y + new_height, top_left_x:top_left_x + new_width]

        return cropped

    def get_features(self, img):
        # Ensure 3-channel BGR image
        if len(img.shape) == 2:
            img_color = cv2.cvtColor(img, cv2.COLOR_GRAY2BGR)
        else:
            img_color = img

        # Resize to consistent shape
        img_color_resized = cv2.resize(img_color, (64, 64), interpolation=cv2.INTER_NEAREST)

        # Split color channels
        B, G, R = cv2.split(img_color_resized)

        # Enhanced RGB features with more statistics
        mean_R = np.mean(R) / 255
        std_R = np.std(R) / 255
        median_R = np.median(R) / 255  # Added median

        mean_G = np.mean(G) / 255
        std_G = np.std(G) / 255
        median_G = np.median(G) / 255  # Added median

        mean_B = np.mean(B) / 255
        std_B = np.std(B) / 255
        median_B = np.median(B) / 255  # Added median

        rgb_features = [mean_R, std_R, median_R, mean_G, std_G, median_G, mean_B, std_B, median_B]

        # Enhanced HSV color space features
        hsv = cv2.cvtColor(img_color_resized, cv2.COLOR_BGR2HSV)
        H, S, V = cv2.split(hsv)

        mean_H = np.mean(H) / 180  # Hue is in [0, 180]
        std_H = np.std(H) / 180  # Added std for hue
        mean_S = np.mean(S) / 255
        std_S = np.std(S) / 255  # Added std for saturation
        mean_V = np.mean(V) / 255
        std_V = np.std(V) / 255  # Added std for value

        hsv_features = [mean_H, std_H, mean_S, std_S, mean_V, std_V]

        # Add color dominance features (using your existing method)
        top_colors = self.top_colors_bgr(img_color_resized, top_n=3, return_one_color=False)
        dominance_features = []
        for i in range(3):
            if i < len(top_colors):
                dominance_features.append(top_colors[i][2] / 100.0)  # Percentage normalized
            else:
                dominance_features.append(0.0)

        # Convert to grayscale for HOG (keep your existing HOG setup)
        gray = cv2.cvtColor(img_color_resized, cv2.COLOR_BGR2GRAY)
        gray_resized = cv2.resize(gray, (32, 32), interpolation=cv2.INTER_NEAREST)

        # Cache HOG descriptor for better performance
        if not hasattr(self, 'hog_descriptor'):
            self.hog_descriptor = cv2.HOGDescriptor(
                _winSize=(32, 32),
                _blockSize=(16, 16),
                _blockStride=(8, 8),
                _cellSize=(8, 8),
                _nbins=9
            )

        hog_features = self.hog_descriptor.compute(gray_resized).flatten()

        # Add simple texture features
        # Edge density
        edges = cv2.Canny(gray_resized, 50, 150)
        edge_density = np.sum(edges > 0) / (32 * 32)

        # Gradient features
        grad_x = cv2.Sobel(gray_resized, cv2.CV_64F, 1, 0, ksize=3)
        grad_y = cv2.Sobel(gray_resized, cv2.CV_64F, 0, 1, ksize=3)
        gradient_magnitude = np.sqrt(grad_x ** 2 + grad_y ** 2)
        mean_gradient = np.mean(gradient_magnitude) / 255.0

        texture_features = [edge_density, mean_gradient]

        # Feature weights (adjusted for better balance)
        COLOR_WEIGHT = 2.5  # Increased for RGB
        HSV_WEIGHT = 2.0  # Increased for HSV
        DOMINANCE_WEIGHT = 1.5  # New weight for color dominance
        HOG_WEIGHT = 0.25  # Reduced HOG impact
        TEXTURE_WEIGHT = 1.0  # New weight for texture

        # Apply weights
        color_features = np.array(rgb_features) * COLOR_WEIGHT
        hsv_features_weighted = np.array(hsv_features) * HSV_WEIGHT
        dominance_features_weighted = np.array(dominance_features) * DOMINANCE_WEIGHT
        hog_features_weighted = np.array(hog_features) * HOG_WEIGHT
        texture_features_weighted = np.array(texture_features) * TEXTURE_WEIGHT

        # Combine all features
        return np.concatenate([color_features, hsv_features_weighted, dominance_features_weighted,
                               hog_features_weighted, texture_features_weighted])


    def recognition(self, camera, mapping ,window_name="Camera"):
        global type
        
        save_dir = "sigmaboy"
        os.makedirs(save_dir, exist_ok=True)
        os.getcwd()

        image = camera.getImage()
        frame = np.frombuffer(image, np.uint8).reshape((camera.getHeight(), camera.getWidth(), 4))
        frame = cv2.cvtColor(frame, cv2.COLOR_BGRA2BGR)
        frame = cv2.resize(frame, (256, 256), interpolation=cv2.INTER_NEAREST)
        frame_gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        # Prepare kernels
        kernel = np.ones((3, 3), np.uint8)

        # --- Laplacian + Sobel combination for adaptive thresholding ---
        laplacian = cv2.Laplacian(frame_gray, cv2.CV_64F, ksize=1)
        sobel_x = cv2.Sobel(frame_gray, cv2.CV_64F, 1, 0, ksize=3)
        sobel_y = cv2.Sobel(frame_gray, cv2.CV_64F, 0, 1, ksize=3)

        laplacian_abs = cv2.convertScaleAbs(laplacian)
        sobel_abs = cv2.convertScaleAbs(np.sqrt(sobel_x ** 2 + sobel_y ** 2))
        combined_edges = cv2.addWeighted(laplacian_abs, 1, sobel_abs, 0, 0)

        # --- Adaptive thresholding ---
        thresh = cv2.adaptiveThreshold(
            combined_edges, 255,
            cv2.ADAPTIVE_THRESH_GAUSSIAN_C,
            cv2.THRESH_BINARY_INV, 11, 2
        )

        thresh = cv2.dilate(thresh, kernel, iterations=1)
        thresh = cv2.erode(thresh, kernel, iterations=1)

        # --- Find contours from thresholded image ---
        contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        letter_frame = frame.copy()
        letter_frame_see = frame.copy()
        cv2.drawContours(letter_frame, contours, -1, (0, 0, 255), 2)
        image_counter = 0
        for i, contour in enumerate(contours):
            area = cv2.contourArea(contour)
            if not (100 <= area <= 30000):
                continue
            rect = cv2.minAreaRect(contour)
            (center, (w, h), angle) = rect  # Extract center, size, and angle

            img_h, img_w = frame.shape[:2]
            if w > 0.93 * img_w or h > 0.93 * img_h:
                continue

            aspect = w / h if w > h else h / w
            if aspect > 1.3:
                continue

            # Shrink the dimensions by 20 pixels on each side (40 pixels total)
            center_y = center[1]
            if abs(center_y - img_h / 2) > 0.12 * img_h:
                continue
            w_shrunk = max(w - 24, 10)  # Ensure width doesn't go below 10 to avoid invalid boxes
            h_shrunk = max(h - 24, 10)  # Ensure height doesn't go below 10
            if w_shrunk < 60 and h_shrunk < 60:
                continue
            box_points = cv2.boxPoints(((center[0], center[1]), (w_shrunk, h_shrunk), angle))
            box_points = box_points.astype(int)
            if np.any(box_points[:, 0] < 0) or np.any(box_points[:, 0] >= img_w) or \
                    np.any(box_points[:, 1] < 0) or np.any(box_points[:, 1] >= img_h):
                continue
            cropped = self.crop_rotated_bounding_box(frame, center, (w_shrunk, h_shrunk), angle)
            cropped = cv2.resize(cropped, (32, 32), interpolation=cv2.INTER_NEAREST)

            resized_pic = cv2.resize(cropped, (32, 32), interpolation=cv2.INTER_NEAREST)
            # Recreate the minAreaRect with shrunken dimensions
            rect_shrunk = ((center[0], center[1]), (w_shrunk, h_shrunk), angle)
            box_shrunk = np.int32(cv2.boxPoints(rect_shrunk))
            # Draw the rotated bounding box in green
            cv2.drawContours(letter_frame_see, [box_shrunk], 0, (0, 255, 0), 2)

            # Check if the cropped image's dominant color is in ignore_colors or ignore_sign_colors
            
            if cropped is not None:  # Ensure cropped image is valid
                image_filename = os.path.join(save_dir,
                                            f"letter_{image_counter}_{type if 'type' in locals() else 'unknown'}.png")
                cv2.imwrite(image_filename, cv2.resize(cropped, (64, 64), interpolation=cv2.INTER_NEAREST))
                print(f"Saved cropped image: {image_filename}")
                image_counter += 1
            
            if w_shrunk > 60 and h_shrunk > 60:
                type = self.determine_image_type(resized_pic)
                if type != "G" and mapping.check_line(self.rotation_diff):
                    self.detected_image = True
            else:
                continue

            # Add label near the center
            center = (int(center[0]), int(center[1]))
            cv2.putText(letter_frame_see, f"Letter_{type}", (center[0] - 20, center[1] - 10),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 255, 0), 2)

    def top_colors_bgr(self, image, top_n=5, return_one_color=False):
        """
        Extracts and counts the most common colors in a NumPy array (BGR image).

        Args:
        - image (numpy.ndarray): Input image in BGR format.
        - top_n (int): Number of most common colors to return.
        - return_one_color (bool): If True, return one color instead of returning a list of n colors.

        Returns:
        - list: A list of tuples [(B, G, R), count], sorted by count in descending order.
        - tuple: ((B, G, R), count).
        """
        # Flatten image from (H, W, 3) to (N, 3) list of BGR tuples
        unique_colors, counts = np.unique(image.reshape(-1, 3), axis=0, return_counts=True)

        if len(unique_colors) < top_n:
            top_n = len(unique_colors)

        # Get indices that would sort the counts in descending order
        sorted_indices = np.argsort(counts)[::-1]
        # Number of pixels
        pixels = sum(counts)

        # Extract the top N colors
        top_colors = [(tuple(unique_colors[i]), counts[i], counts[i] * 100 / pixels) for i in sorted_indices[:top_n]]

        if return_one_color:
            return top_colors[top_n - 1]
        return top_colors[:top_n]
    
class Mapping:
    def __init__(self, gps_values, rotation_values, lidar_points):
        self.GPS_X_OFFSET = round(gps_values[2] * 100, 2)
        self.GPS_Y_OFFSET = round(gps_values[0] * 100, 2)

        self.CELL_SIZE = 1

        self.robot_x_position = 0
        self.robot_y_position = 0
        self.robot_z_axis_rotation = rotation_values[2]
        self.robot_x_axis_rotation = rotation_values[0]
        self.robot_y_axis_rotation = rotation_values[1]
        self.grid_center_x = None
        self.grid_center_y = None

        self.map = None

        self.special_tiles = {
            (0, 0): "5",
        }

        self.occupied_cells = (2, 4)
        self.free_cells = (1, 3)

        self.lidar_points = [[p.x * 100, p.y * 100, p.z * 100] for p in lidar_points]

        self.grid = self._create_grid()

    """ Update method for all the values that are read from the sensors 
    
    Returns
    -------
    None """
    def update_mapping_values(self, gps_values, rotation_values, lidar_points):
        self.robot_x_position = round((gps_values[2] * 100) - self.GPS_X_OFFSET, 2)
        self.robot_y_position = round((gps_values[0] * 100) - self.GPS_Y_OFFSET, 2)
        self.robot_x_axis_rotation = rotation_values[0]
        self.robot_y_axis_rotation = rotation_values[1]
        self.robot_z_axis_rotation = rotation_values[2]
        self.lidar_points = [[p.x * 100, p.y * 100, p.z * 100] for p in lidar_points]

    def _create_grid(self):
        grid_width = 1
        grid_height = 1
        self.grid_center_x = grid_width // 2
        self.grid_center_y = grid_height // 2
        return np.full((grid_width, grid_height), -1, dtype=np.int32)

    """ Write method manages dynamic grid, checks if it needs to be resized and writes data (num_type) inside cells

    Returns
    -------
    None """
    def _update_grid(self, point_x, point_y, num_type):
        pad_top = 0
        pad_bottom = 0
        pad_left = 0
        pad_right = 0

        # Refactoring GPS points into grid form
        grid_related_point_x, grid_related_point_y = point_x + self.grid_center_x, point_y + self.grid_center_y
        grid_height, grid_width = self.grid.shape

        #Checking if grid resizing is needed
        if grid_related_point_x >= grid_width:
            pad_right = grid_related_point_x - grid_width + 2
            if pad_right % 2 != 0: pad_right += 1

        elif grid_related_point_x != abs(grid_related_point_x):
            pad_left = abs(grid_related_point_x) + 2
            if pad_left % 2 != 0: pad_left += 1

        if grid_related_point_y >= grid_height:
            pad_bottom = grid_related_point_y - grid_height + 2
            if pad_bottom % 2 != 0: pad_bottom += 1

        elif grid_related_point_y != abs(grid_related_point_y):
            pad_top = abs(grid_related_point_y) + 2
            if pad_top % 2 != 0: pad_top += 1

        # Resizing grid
        if pad_top > 0 or pad_bottom > 0 or pad_left > 0 or pad_right > 0:
            self.grid = np.pad(self.grid, ((pad_top, pad_bottom), (pad_left, pad_right)), mode='constant', constant_values=-1)
            self.grid_center_x += pad_left
            self.grid_center_y += pad_top

        grid_related_point_x = point_x + self.grid_center_x
        grid_related_point_y = point_y + self.grid_center_y
        # Writing data to grid

        self.grid[grid_related_point_y, grid_related_point_x] = max(num_type, self.grid[grid_related_point_y, grid_related_point_x])

    """ Calc method using Bresenham algorithm for determining where are valid free cells are and adding them to sets and grid
    
    Returns
    -------
    None """
    def _bresenham_algorithm(self, x0, y0, x1, y1, val):
        # ? Only Matej knows what these variables mean and how this works
        # TODO: Rename variables and document this
        dx = abs(x1 - x0)
        dy = abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy

        while x0 != x1 and y0 != y1:
            try:
                self._update_grid(x0, y0, val)
            except: pass
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x0 += sx
            if e2 < dx:
                err += dx
                y0 += sy
    
    def check_line(self, rotation_diff):
        count = 7
        """
        Traces a line from a source point at a given rotation for a certain number of steps.
        Checks if there's a occupied cell on the grid at each step.

        Args:
            rotation_diff (float): angle in radians.

        Returns:
            boolean: is there is possibility of token or not.
        """
        x, y = (int(round(self.robot_x_position)) + self.grid_center_x, int(round(self.robot_y_position)) + self.grid_center_y)

        # Directional increments per step
        dx = math.cos(self.robot_z_axis_rotation + rotation_diff) * -1
        dy = math.sin(self.robot_z_axis_rotation + rotation_diff) * -1

        for i in range(1, count + 1):
            check_x = int(round(x + dx * i))
            check_y = int(round(y + dy * i))

            # Make sure we're within the grid boundaries
            if 0 <= check_x < len(self.grid[0]) and 0 <= check_y < len(self.grid):
                if self.grid[check_y][check_x] in self.occupied_cells:
                    print(f"({check_x - self.grid_center_x}, {check_y - self.grid_center_y}) == 1")
                    return True
        print(f"({check_x - self.grid_center_x}, {check_y - self.grid_center_y}) == 0")
        return False

    """ Transform method used for calculating the point position in grid format
    (values can be negative)

    Returns
    -------
    tuple
       - x and y position of point in format usable in grid """
    def _world_to_grid_format(self, x, y):
        grid_x = int(round(x / self.CELL_SIZE))
        grid_y = int(round(y / self.CELL_SIZE))
        return grid_x, grid_y

    """Transform method for rotating and placing LIDAR points into GPS points using rotation matrix and robot coordinates

    Returns
    -------
    tuple
       - x and y position of point in GPS relative format """
    def _transform_lidar_point(self, local_x, local_y):
        # Rotation using matrix
        matrix = np.array([
            [math.cos(self.robot_z_axis_rotation), -math.sin(self.robot_z_axis_rotation)],
            [math.sin(self.robot_z_axis_rotation), math.cos(self.robot_z_axis_rotation)]
        ])

        coords_matrix = np.array([[local_x], [local_y]])
        new_coords_matrix = matrix @ coords_matrix

        # Placement into GPS
        world_x = new_coords_matrix[0, 0] + self.robot_x_position
        world_y = new_coords_matrix[1, 0] + self.robot_y_position

        return float(world_x), float(world_y)

    """Main method going through all lidar points and passing them into other methods
     
    Returns
    -------
    None """
    def check_points(self):
        if (abs(self.robot_x_axis_rotation) < 0.01 and abs(self.robot_y_axis_rotation) < 0.01):
            for point in self.lidar_points:
                x, y, z = point
                if np.isfinite(x) and np.isfinite(y) and np.isfinite(z) and z > -2:
                    d = math.sqrt(x ** 2 + y ** 2)
                    multiplier = 1 if d > 18 else 2
                    free_cell_val = 1 if multiplier == 1 else 3
                    occupied_cell_val = 2 * multiplier

                    world_point_x, world_point_y = self._transform_lidar_point(x, y)

                    grid_point_x, grid_point_y = self._world_to_grid_format(world_point_x, world_point_y)
                    grid_robot_x, grid_robot_y = self._world_to_grid_format(self.robot_x_position, self.robot_y_position)

                    self._bresenham_algorithm(grid_robot_x, grid_robot_y, grid_point_x, grid_point_y, free_cell_val)
                    # Pass duplicates

                    self._update_grid(point_x=grid_point_x, point_y=grid_point_y, num_type=occupied_cell_val)

    """Debug method for grid

    Returns
    -------
    None """
    def display_grid(self):
        # Define colors
        color_map = {
            -1: (0, 0, 0),  # Black
            1: (255, 255, 255),  # White
            2: (0, 255, 0),
            3: (255, 200, 200),
            4: (0, 0, 255)  # Green
        }

        # Convert grid to an RGB image
        height, width = self.grid.shape
        img = np.zeros((width, height, 3), dtype=np.uint8)

        for y in range(height):
            for x in range(width):
                img[x, y] = color_map[self.grid[y, x]]

        # Scale the image for better visibility
        scale = 5  # Change this to adjust the size
        img_resized = cv2.resize(img, (height * scale, width * scale), interpolation=cv2.INTER_NEAREST)

        # Display the image
        cv2.imshow("Grid", img_resized)


    def refactor_grid(self):
        grid_height, grid_width =  self.grid.shape # 30 + self.grid_center_x, 30 + self.grid_center_y
        start_x, start_y = 0 + self.grid_center_x, 0 + self.grid_center_y
        while start_x - 18 > 0:
            start_x -= 12
        while start_y - 18 > 0:
            start_y -= 12
        for y in range(start_y, grid_height - 6 + 1, 12):
            row = None  # List to collect the tiles for this row
            for x in range(start_x, grid_width - 6 + 1, 12):
                tile = self.refactor_tile(x, y, top_border=y == start_y, left_border=x == start_x)
            
                if row is None:
                    row = tile  # Initialize the map if it's None
                else:
                    row = np.hstack((row, tile))
            
            # Vertically stack this row to the map
            if self.map is None:
                self.map = row  # Initialize the map if it's None
            else:
                self.map = np.vstack((self.map, row))  # Append the row to the map
        
        print(self.map)
        
    def refactor_tile(self, src_x, src_y, left_border=False, top_border=False, right_border=True, bottom_border=True):
        # Init
        tile_width, tile_height = 3, 3
        tile_center_x, tile_center_y = 1, 1

        if left_border:
            tile_width += 1
            tile_center_x += 1

        if right_border:
            tile_width += 1

        if top_border:
            tile_height += 1
            tile_center_y += 1

        if bottom_border:
            tile_height += 1
        
        tile = np.full((tile_height, tile_width), "0")

        # Content
        node = (src_x - self.grid_center_x, src_y - self.grid_center_y)
        if node in self.special_tiles.keys():
            tile[tile_center_y - 1][tile_center_x - 1] = self.special_tiles[node]
            tile[tile_center_y - 1][tile_center_x + 1] = self.special_tiles[node]
            tile[tile_center_y + 1][tile_center_x - 1] = self.special_tiles[node]
            tile[tile_center_y + 1][tile_center_x + 1] = self.special_tiles[node]
        else:
            # Corners
            tile[tile_center_y - 1][tile_center_x - 1] = "1" if self.grid[src_y - 2][src_x - 2] in self.occupied_cells else "0"
            tile[tile_center_y - 1][tile_center_x + 1] = "1" if self.grid[src_y - 2][src_x + 2] in self.occupied_cells else "0"
            tile[tile_center_y + 1][tile_center_x - 1] = "1" if self.grid[src_y + 2][src_x - 2] in self.occupied_cells else "0"
            tile[tile_center_y + 1][tile_center_x + 1] = "1" if self.grid[src_y + 2][src_x + 2] in self.occupied_cells else "0"
            
            # Edges
